//! Configuration compatibility tests for downstream HTTP MCP servers.

use server::engine::mcp_client::{McpServerAuth, McpServerConfig, McpServerTransport};

#[test]
fn deserializes_minimal_http_oauth_browser_config() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "calendar",
            "transport": "http",
            "url": "https://calendar.example.com/mcp",
            "auth": { "type": "oauth_browser" }
        }"#,
    )
    .expect("minimal HTTP OAuth browser configuration should deserialize");

    assert!(matches!(
        config.transport,
        McpServerTransport::Http { ref url }
            if url == "https://calendar.example.com/mcp"
    ));
    assert!(matches!(
        config.auth,
        Some(McpServerAuth::OauthBrowser {
            scope: None,
            client_id: None,
            client_secret: None,
            redirect_port: None,
            token_cache: None,
        })
    ));
}

#[test]
fn deserializes_fully_specified_http_oauth_browser_config() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "calendar",
            "transport": "http",
            "url": "https://calendar.example.com/mcp",
            "auth": {
                "type": "oauth_browser",
                "scope": ["calendar.read", "calendar.write"],
                "client_id": "calendar-cli",
                "client_secret": "secret",
                "redirect_port": 8080,
                "token_cache": "/tmp/calendar-tokens.json"
            }
        }"#,
    )
    .expect("fully specified HTTP OAuth browser configuration should deserialize");

    assert!(matches!(
        config.auth,
        Some(McpServerAuth::OauthBrowser {
            scope: Some(ref scope),
            client_id: Some(ref client_id),
            client_secret: Some(ref client_secret),
            redirect_port: Some(8080),
            token_cache: Some(ref token_cache),
        }) if scope == &["calendar.read", "calendar.write"]
            && client_id == "calendar-cli"
            && client_secret == "secret"
            && token_cache == "/tmp/calendar-tokens.json"
    ));
}

#[test]
fn keeps_stdio_transport_when_auth_is_present() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "legacy",
            "transport": "stdio",
            "command": "legacy-mcp",
            "auth": { "type": "oauth_browser" }
        }"#,
    )
    .expect("stdio auth is retained in configuration and ignored by the transport");

    assert!(matches!(
        config.transport,
        McpServerTransport::Stdio { ref command, .. } if command == "legacy-mcp"
    ));
    assert!(matches!(
        config.auth,
        Some(McpServerAuth::OauthBrowser { .. })
    ));
}

#[test]
fn keeps_legacy_sse_config_working() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "legacy-sse",
            "transport": "sse",
            "url": "https://legacy.example.com/sse"
        }"#,
    )
    .expect("legacy SSE configuration should still deserialize");

    assert!(matches!(
        config.transport,
        McpServerTransport::Sse { ref url } if url == "https://legacy.example.com/sse"
    ));
    assert!(config.auth.is_none());
}

#[test]
fn permits_http_oauth_but_keeps_sse_auth_fail_closed() {
    let http: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "protected-http",
            "transport": "http",
            "url": "https://protected.example.com/mcp",
            "auth": { "type": "oauth_browser" }
        }"#,
    )
    .expect("HTTP auth configuration should deserialize");
    http.validate_for_connection()
        .expect("HTTP OAuth runtime is available");

    let sse: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "protected-sse",
            "transport": "sse",
            "url": "https://protected.example.com/mcp",
            "auth": { "type": "oauth_browser" }
        }"#,
    )
    .expect("SSE auth configuration should deserialize");
    let error = sse
        .validate_for_connection()
        .expect_err("SSE auth must remain fail closed");
    assert!(error.contains("OAuth runtime support is not implemented"));
    assert!(error.contains("SSE"));
}

#[test]
fn permits_stdio_auth_configuration_for_legacy_compatibility() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "legacy",
            "transport": "stdio",
            "command": "legacy-mcp",
            "auth": { "type": "oauth_browser" }
        }"#,
    )
    .expect("stdio auth configuration should deserialize");

    config
        .validate_for_connection()
        .expect("stdio auth remains ignored with a warning for compatibility");
}

#[test]
fn debug_output_redacts_oauth_client_secrets() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "calendar",
            "transport": "http",
            "url": "https://calendar.example.com/mcp",
            "auth": {
                "type": "oauth_browser",
                "client_id": "calendar-cli",
                "client_secret": "client-secret"
            }
        }"#,
    )
    .expect("OAuth configuration should deserialize");

    let debug = format!("{config:?}");
    assert!(!debug.contains("client-secret"));
    assert!(debug.contains("[REDACTED]"));
}

#[test]
fn rejects_client_secret_without_client_id() {
    let config: McpServerConfig = serde_json::from_str(
        r#"{
            "name": "calendar",
            "transport": "http",
            "url": "https://calendar.example.com/mcp",
            "auth": {
                "type": "oauth_browser",
                "client_secret": "orphan-secret"
            }
        }"#,
    )
    .expect("configuration should deserialize before connection validation");

    let error = config
        .validate_for_connection()
        .expect_err("client_secret without client_id must fail closed");
    assert!(error.contains("client_secret"));
    assert!(error.contains("client_id"));
}

//! Headless end-to-end coverage for downstream browser OAuth.

use std::collections::{HashMap, HashSet};
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::Duration;

use axum::extract::{Form, Query, Request, State};
use axum::http::{HeaderMap, HeaderValue, StatusCode};
use axum::middleware::{self, Next};
use axum::response::{IntoResponse, Response};
use axum::{
    Json, Router,
    routing::{get, post},
};
use rmcp::{
    ServerHandler,
    handler::server::{router::tool::ToolRouter, wrapper::Parameters},
    model::{ServerCapabilities, ServerInfo},
    schemars, tool, tool_handler, tool_router,
    transport::streamable_http_server::{
        StreamableHttpServerConfig, StreamableHttpService, session::local::LocalSessionManager,
    },
};
use serde_json::{Value, json};
use server::engine::mcp_client::{
    McpClientManager, McpServerAuth, McpServerConfig, McpServerTransport,
};
use tokio_util::sync::CancellationToken;

static ENVIRONMENT_LOCK: OnceLock<Mutex<()>> = OnceLock::new();

#[derive(Debug, serde::Deserialize, schemars::JsonSchema)]
struct EmptyInput {}

#[derive(Clone)]
struct ProtectedMcp {
    tool_router: ToolRouter<Self>,
}

impl ProtectedMcp {
    fn new() -> Self {
        Self {
            tool_router: Self::tool_router(),
        }
    }
}

#[tool_router]
impl ProtectedMcp {
    #[tool(description = "Confirms the protected MCP server is available")]
    fn browser_oauth_tool(&self, _: Parameters<EmptyInput>) -> String {
        "connected".to_string()
    }
}

#[tool_handler(router = self.tool_router)]
impl ServerHandler for ProtectedMcp {
    fn get_info(&self) -> ServerInfo {
        ServerInfo::new(ServerCapabilities::builder().enable_tools().build())
    }
}

#[derive(Clone)]
struct MockState {
    base_url: String,
    authorization_requests: Arc<AtomicUsize>,
    registration_requests: Arc<AtomicUsize>,
    token_grants: Arc<Mutex<Vec<HashMap<String, String>>>>,
    token_authorizations: Arc<Mutex<Vec<Option<String>>>>,
    mcp_tokens: Arc<Mutex<Vec<String>>>,
    accepted_tokens: Arc<Mutex<HashSet<String>>>,
}

struct MockOAuthMcpServer {
    base_url: String,
    state: MockState,
    cancellation: CancellationToken,
    task: tokio::task::JoinHandle<()>,
}

impl MockOAuthMcpServer {
    async fn start() -> Result<Self, Box<dyn std::error::Error>> {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
        let base_url = format!("http://{}", listener.local_addr()?);
        let state = MockState {
            base_url: base_url.clone(),
            authorization_requests: Arc::new(AtomicUsize::new(0)),
            registration_requests: Arc::new(AtomicUsize::new(0)),
            token_grants: Arc::new(Mutex::new(Vec::new())),
            token_authorizations: Arc::new(Mutex::new(Vec::new())),
            mcp_tokens: Arc::new(Mutex::new(Vec::new())),
            accepted_tokens: Arc::new(Mutex::new(HashSet::new())),
        };
        let cancellation = CancellationToken::new();
        let mcp_service: StreamableHttpService<ProtectedMcp, LocalSessionManager> =
            StreamableHttpService::new(
                || Ok(ProtectedMcp::new()),
                LocalSessionManager::default().into(),
                StreamableHttpServerConfig::default()
                    .with_sse_keep_alive(None)
                    .with_cancellation_token(cancellation.child_token()),
            );
        let mcp_routes = Router::new().nest_service("/mcp", mcp_service).route_layer(
            middleware::from_fn_with_state(state.clone(), require_access_token),
        );
        let app = Router::new()
            .route(
                "/.well-known/oauth-protected-resource/mcp",
                get(protected_resource_metadata),
            )
            .route(
                "/.well-known/oauth-authorization-server",
                get(authorization_metadata),
            )
            .route("/register", post(register_client))
            .route("/authorize", get(authorize))
            .route("/token", post(token))
            .merge(mcp_routes)
            .with_state(state.clone());
        let shutdown = cancellation.clone();
        let task = tokio::spawn(async move {
            let _ = axum::serve(listener, app)
                .with_graceful_shutdown(async move { shutdown.cancelled_owned().await })
                .await;
        });

        Ok(Self {
            base_url,
            state,
            cancellation,
            task,
        })
    }

    fn mcp_url(&self) -> String {
        format!("{}/mcp", self.base_url)
    }
}

impl Drop for MockOAuthMcpServer {
    fn drop(&mut self) {
        self.cancellation.cancel();
        self.task.abort();
    }
}

async fn protected_resource_metadata(State(state): State<MockState>) -> Json<Value> {
    Json(json!({"authorization_servers": [state.base_url]}))
}

async fn authorization_metadata(State(state): State<MockState>) -> Json<Value> {
    Json(json!({
        "issuer": state.base_url,
        "authorization_endpoint": format!("{}/authorize", state.base_url),
        "token_endpoint": format!("{}/token", state.base_url),
        "registration_endpoint": format!("{}/register", state.base_url),
        "token_endpoint_auth_methods_supported": ["client_secret_post"],
        "response_types_supported": ["code"],
        "code_challenge_methods_supported": ["S256"]
    }))
}

async fn register_client(
    State(state): State<MockState>,
    Json(request): Json<Value>,
) -> Json<Value> {
    state.registration_requests.fetch_add(1, Ordering::SeqCst);
    assert_eq!(request["token_endpoint_auth_method"], "client_secret_post");
    Json(json!({
        "client_id": "headless-test-client",
        "client_secret": "dcr-secret",
        "token_endpoint_auth_method": "client_secret_post",
        "client_name": request["client_name"],
        "redirect_uris": request["redirect_uris"]
    }))
}

async fn authorize(
    State(state): State<MockState>,
    Query(_query): Query<HashMap<String, String>>,
) -> StatusCode {
    state.authorization_requests.fetch_add(1, Ordering::SeqCst);
    StatusCode::OK
}

async fn token(
    State(state): State<MockState>,
    headers: HeaderMap,
    Form(form): Form<HashMap<String, String>>,
) -> Response {
    let grant_type = form.get("grant_type").cloned().unwrap_or_default();
    let authorization = headers
        .get("authorization")
        .and_then(|value| value.to_str().ok())
        .map(str::to_string);
    state
        .token_authorizations
        .lock()
        .unwrap()
        .push(authorization.clone());
    state.token_grants.lock().unwrap().push(form.clone());
    if authorization.is_some()
        || form.get("client_id") != Some(&"headless-test-client".to_string())
        || form.get("client_secret") != Some(&"dcr-secret".to_string())
    {
        return (
            StatusCode::UNAUTHORIZED,
            Json(json!({"error": "invalid_client"})),
        )
            .into_response();
    }
    let access_token = match grant_type.as_str() {
        "authorization_code" => "browser-access",
        "refresh_token" => "refreshed-access",
        other => panic!("unexpected OAuth grant type: {other}"),
    };
    state
        .accepted_tokens
        .lock()
        .unwrap()
        .insert(access_token.to_string());
    Json(json!({
        "access_token": access_token,
        "token_type": "Bearer",
        "refresh_token": if grant_type == "authorization_code" { "browser-refresh" } else { "rotated-refresh" },
        "expires_in": 3600
    }))
    .into_response()
}

async fn require_access_token(
    State(state): State<MockState>,
    request: Request,
    next: Next,
) -> Response {
    let token = request
        .headers()
        .get("authorization")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .unwrap_or_default()
        .to_string();
    let accepted = state.accepted_tokens.lock().unwrap().contains(&token);
    if !accepted {
        return (
            StatusCode::UNAUTHORIZED,
            [("www-authenticate", HeaderValue::from_static("Bearer"))],
        )
            .into_response();
    }
    state.mcp_tokens.lock().unwrap().push(token);
    next.run(request).await
}

struct EnvironmentGuard {
    previous_path: Option<OsString>,
    previous_capture: Option<OsString>,
}

impl EnvironmentGuard {
    fn install(bin_dir: &Path, capture_path: &Path) -> Self {
        let previous_path = std::env::var_os("PATH");
        let previous_capture = std::env::var_os("MCP_OAUTH_CAPTURE");
        let mut paths = vec![bin_dir.to_path_buf()];
        paths.extend(std::env::split_paths(
            previous_path.as_deref().unwrap_or_default(),
        ));
        // The production opener remains unchanged; only this test process resolves its shim first.
        unsafe {
            std::env::set_var("PATH", std::env::join_paths(paths).unwrap());
            std::env::set_var("MCP_OAUTH_CAPTURE", capture_path);
        }
        Self {
            previous_path,
            previous_capture,
        }
    }
}

impl Drop for EnvironmentGuard {
    fn drop(&mut self) {
        unsafe {
            match &self.previous_path {
                Some(value) => std::env::set_var("PATH", value),
                None => std::env::remove_var("PATH"),
            }
            match &self.previous_capture {
                Some(value) => std::env::set_var("MCP_OAUTH_CAPTURE", value),
                None => std::env::remove_var("MCP_OAUTH_CAPTURE"),
            }
        }
    }
}

#[cfg(unix)]
fn install_headless_browser(
    directory: &Path,
) -> Result<(PathBuf, EnvironmentGuard), Box<dyn std::error::Error>> {
    use std::os::unix::fs::PermissionsExt;

    let bin_dir = directory.join("bin");
    std::fs::create_dir(&bin_dir)?;
    let capture_path = directory.join("authorization-url");
    let opener = bin_dir.join("xdg-open");
    std::fs::write(
        &opener,
        "#!/bin/sh\nprintf '%s\\n' \"$1\" >> \"$MCP_OAUTH_CAPTURE\"\n",
    )?;
    std::fs::set_permissions(&opener, std::fs::Permissions::from_mode(0o755))?;
    let guard = EnvironmentGuard::install(&bin_dir, &capture_path);
    Ok((capture_path, guard))
}

fn opener_invocations(path: &Path) -> usize {
    std::fs::read_to_string(path)
        .map(|captured| captured.lines().count())
        .unwrap_or(0)
}

async fn wait_for_authorization_url(path: &Path) -> Result<url::Url, Box<dyn std::error::Error>> {
    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            if let Ok(url) = std::fs::read_to_string(path) {
                if let Ok(url) = url.trim().parse() {
                    return url;
                }
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await
    .map_err(|_| "timed out waiting for the headless browser URL".into())
}

fn pkce_s256(verifier: &str) -> String {
    use sha2::{Digest, Sha256};

    const BASE64_URL: &[u8; 64] =
        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let digest = Sha256::digest(verifier.as_bytes());
    let mut encoded = String::new();
    for chunk in digest.chunks(3) {
        let value = (u32::from(chunk[0]) << 16)
            | (u32::from(*chunk.get(1).unwrap_or(&0)) << 8)
            | u32::from(*chunk.get(2).unwrap_or(&0));
        encoded.push(BASE64_URL[((value >> 18) & 0x3f) as usize] as char);
        encoded.push(BASE64_URL[((value >> 12) & 0x3f) as usize] as char);
        if chunk.len() > 1 {
            encoded.push(BASE64_URL[((value >> 6) & 0x3f) as usize] as char);
        }
        if chunk.len() > 2 {
            encoded.push(BASE64_URL[(value & 0x3f) as usize] as char);
        }
    }
    encoded
}

fn browser_oauth_config(server: &MockOAuthMcpServer, cache_path: &Path) -> McpServerConfig {
    McpServerConfig {
        name: "protected".to_string(),
        transport: McpServerTransport::Http {
            url: server.mcp_url(),
        },
        auth: Some(McpServerAuth::OauthBrowser {
            scope: Some(vec!["tools.read".to_string()]),
            client_id: None,
            client_secret: None,
            redirect_port: Some(0),
            token_cache: Some(cache_path.display().to_string()),
        }),
    }
}

#[cfg(unix)]
#[tokio::test]
async fn browser_oauth_authorizes_reuses_cache_and_refreshes_headlessly()
-> Result<(), Box<dyn std::error::Error>> {
    let _environment_lock = ENVIRONMENT_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .unwrap();
    let directory = tempfile::tempdir()?;
    let (capture_path, _environment_guard) = install_headless_browser(directory.path())?;
    let server = MockOAuthMcpServer::start().await?;
    let cache_path = directory.path().join("oauth-cache.json");
    let config = browser_oauth_config(&server, &cache_path);

    let mut first_connection = tokio::spawn(McpClientManager::connect(vec![config.clone()]));
    let authorization_url = tokio::select! {
        result = &mut first_connection => match result {
            Ok(Err(error)) => return Err(error.into()),
            Ok(Ok(_)) => return Err("OAuth connection succeeded without opening a browser".into()),
            Err(error) => return Err(error.into()),
        },
        url = wait_for_authorization_url(&capture_path) => url?,
    };
    let query: HashMap<_, _> = authorization_url.query_pairs().into_owned().collect();
    assert_eq!(authorization_url.path(), "/authorize");
    assert_eq!(
        query.get("code_challenge_method"),
        Some(&"S256".to_string())
    );
    assert!(
        query
            .get("code_challenge")
            .is_some_and(|value| !value.is_empty())
    );
    let state = query.get("state").expect("authorization state").to_string();
    let redirect_uri = query.get("redirect_uri").expect("redirect URI").to_string();
    assert_eq!(opener_invocations(&capture_path), 1);

    reqwest::get(authorization_url.clone())
        .await?
        .error_for_status()?;
    let rejected_callback = url::Url::parse_with_params(
        &redirect_uri,
        [("code", "wrong-state-code"), ("state", "wrong-state")],
    )?;
    reqwest::get(rejected_callback).await?.error_for_status()?;
    assert!(
        tokio::time::timeout(Duration::from_millis(150), &mut first_connection)
            .await
            .is_err(),
        "a callback with the wrong state must not complete OAuth"
    );

    let callback = url::Url::parse_with_params(
        &redirect_uri,
        [("code", "headless-code"), ("state", &state)],
    )?;
    reqwest::get(callback).await?.error_for_status()?;
    let first = first_connection.await??;
    let tools = first.list_tools(Some("protected"))?;
    assert_eq!(tools.len(), 1);
    assert_eq!(tools[0].name, "browser_oauth_tool");
    drop(first);

    let grants = server.state.token_grants.lock().unwrap().clone();
    assert_eq!(grants.len(), 1);
    assert_eq!(
        grants[0].get("grant_type"),
        Some(&"authorization_code".to_string())
    );
    assert_eq!(grants[0].get("code"), Some(&"headless-code".to_string()));
    assert_eq!(
        grants[0].get("client_secret"),
        Some(&"dcr-secret".to_string())
    );
    let verifier = grants[0].get("code_verifier").expect("PKCE verifier");
    assert_eq!(pkce_s256(verifier), *query.get("code_challenge").unwrap());
    assert_eq!(
        server.state.authorization_requests.load(Ordering::SeqCst),
        1
    );
    assert_eq!(server.state.registration_requests.load(Ordering::SeqCst), 1);

    let cached = tokio::time::timeout(
        Duration::from_secs(2),
        McpClientManager::connect(vec![config.clone()]),
    )
    .await
    .map_err(|_| "cache reuse unexpectedly waited for browser authorization")??;
    assert_eq!(cached.list_tools(Some("protected"))?.len(), 1);
    drop(cached);
    assert_eq!(opener_invocations(&capture_path), 1);
    assert_eq!(
        server.state.authorization_requests.load(Ordering::SeqCst),
        1
    );
    assert_eq!(server.state.registration_requests.load(Ordering::SeqCst), 1);
    assert_eq!(server.state.token_grants.lock().unwrap().len(), 1);

    server
        .state
        .accepted_tokens
        .lock()
        .unwrap()
        .remove("browser-access");

    let refreshed = tokio::time::timeout(
        Duration::from_secs(2),
        McpClientManager::connect(vec![config.clone()]),
    )
    .await
    .map_err(|_| "revoked cached token recovery unexpectedly waited for browser authorization")??;
    assert_eq!(refreshed.list_tools(Some("protected"))?.len(), 1);
    assert_eq!(opener_invocations(&capture_path), 1);
    let grants = server.state.token_grants.lock().unwrap().clone();
    assert_eq!(grants.len(), 2);
    assert_eq!(
        grants[1].get("grant_type"),
        Some(&"refresh_token".to_string())
    );
    assert_eq!(
        grants[1].get("refresh_token"),
        Some(&"browser-refresh".to_string())
    );
    assert_eq!(
        server.state.authorization_requests.load(Ordering::SeqCst),
        1
    );
    assert_eq!(server.state.registration_requests.load(Ordering::SeqCst), 1);
    let token_authorizations = server.state.token_authorizations.lock().unwrap().clone();
    assert!(token_authorizations[0].is_none() && token_authorizations[1].is_none());
    assert_eq!(
        grants[1].get("client_secret"),
        Some(&"dcr-secret".to_string())
    );
    assert_eq!(
        server.state.mcp_tokens.lock().unwrap().last(),
        Some(&"refreshed-access".to_string())
    );

    drop(refreshed);
    let cache_before_network_failure = std::fs::read(&cache_path)?;
    drop(server);
    assert!(McpClientManager::connect(vec![config]).await.is_err());
    assert_eq!(std::fs::read(&cache_path)?, cache_before_network_failure);

    Ok(())
}

// Bootstrap for running WPT testharness.js tests inside the mcp-v8 engine.
//
// Runs before testharness.js. Provides just enough of a "shell" environment
// that testharness selects its ShellTestEnvironment (no document, no worker
// scopes) and that `.any.js` tests can sniff their scope via self.GLOBAL.
//
// __WPT_TEST_PATH__ is injected by the Rust harness before this file.

globalThis.self = globalThis;

globalThis.GLOBAL = {
  isWindow: function () { return false; },
  isWorker: function () { return false; },
  isShadowRealm: function () { return false; },
};

// Minimal location mock (Node's WPT runner does the same). Gives testharness
// a stable default title and lets tests read location.pathname.
(function () {
  var path = globalThis.__WPT_TEST_PATH__ || "/unknown.any.js";
  // Plain object, NOT a URL instance (url/historical.any.js asserts location
  // has no searchParams), but stringifiable so `new URL(x, location)` works.
  var href = "http://web-platform.test:8000" + path;
  globalThis.location = {
    href: href,
    pathname: path,
    search: "",
    hash: "",
    toString: function () { return href; },
  };
})();

// Serve embedded test resources (resources/*.json, injected by the Rust
// harness as __WPT_RESOURCES__) through fetch, so data-driven tests work
// without a wptserve. Everything else falls through to the real fetch.
(function () {
  var resources = globalThis.__WPT_RESOURCES__ || {};
  var assets = globalThis.__WPT_ASSETS__ || {};
  if (Object.keys(resources).length === 0 && Object.keys(assets).length === 0) return;
  var realFetch = globalThis.fetch;
  function embeddedResponse(text) {
    return Promise.resolve({
      ok: true,
      status: 200,
      json: function () { return Promise.resolve(JSON.parse(text)); },
      text: function () { return Promise.resolve(text); },
      bytes: function () { return Promise.resolve(new TextEncoder().encode(text)); },
      arrayBuffer: function () {
        return Promise.resolve(new TextEncoder().encode(text).buffer);
      },
    });
  }
  // Resolve "../x" / "./x" requests against the test's directory so the
  // absolute-path asset map serves them too.
  function resolveKey(key) {
    if (key.indexOf("../") !== 0 && key.indexOf("./") !== 0) return key;
    var base = String(globalThis.location.pathname).split("/").slice(0, -1);
    var parts = key.split("/");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "..") base.pop();
      else if (parts[i] !== ".") base.push(parts[i]);
    }
    return base.join("/");
  }
  // Deterministic pseudo-random bytes stand in for WPT's large media file:
  // the compression tests only round-trip whatever bytes live at this path.
  var LARGE_ASSET = "/media/test-av-384k-44100Hz-1ch-320x240-30fps-10kfr.webm";
  function largeAssetBytes() {
    // Structured (compressible) data: the output-length tests assert the
    // compressed form is smaller than the input.
    var out = new Uint8Array(1 << 20);
    for (var i = 0; i < out.length; i++) {
      out[i] = (i >> 6) & 0xff;
    }
    return out;
  }
  globalThis.fetch = function fetch(input, init) {
    var key = String(input);
    if (Object.prototype.hasOwnProperty.call(resources, key)) {
      return embeddedResponse(resources[key]);
    }
    var resolved = resolveKey(key);
    if (Object.prototype.hasOwnProperty.call(assets, resolved)) {
      return embeddedResponse(assets[resolved]);
    }
    if (resolved === LARGE_ASSET) {
      var bytes = largeAssetBytes();
      return Promise.resolve({
        ok: true,
        status: 200,
        bytes: function () { return Promise.resolve(bytes.slice(0)); },
        arrayBuffer: function () { return Promise.resolve(bytes.slice(0).buffer); },
        text: function () { return Promise.resolve(new TextDecoder().decode(bytes)); },
        json: function () { return Promise.reject(new TypeError("not json")); },
      });
    }
    if (typeof realFetch === "function") {
      return realFetch.apply(this, arguments);
    }
    return Promise.reject(new TypeError("fetch is not available"));
  };
})();

//! CLI end-to-end integration tests
//!
//! These tests start the mcp-v8 server in stateless HTTP mode, then exercise
//! every mcp-v8-cli subcommand via `std::process::Command`, asserting correct
//! exit codes and output.
//!
//! # Prerequisites
//!
//! Both binaries must be built before running these tests:
//!
//! ```bash
//! # From the workspace root
//! cargo build --release --bin server   -p server
//! cargo build --release --bin mcp-v8-cli -p mcp-v8-client
//! ```
//!
//! # Running
//!
//! ```bash
//! # From the workspace root (or mcp-v8-client/)
//! cargo test --test cli_e2e -p mcp-v8-client -- --nocapture
//! ```
//!
//! To point the tests at a custom server binary set `SERVER_BIN`:
//!
//! ```bash
//! SERVER_BIN=/path/to/server cargo test --test cli_e2e -p mcp-v8-client
//! ```

use reqwest::blocking::Client;
use serde_json::Value;
use std::{
    env,
    net::TcpListener,
    process::{Child, Command, Stdio},
    thread::sleep,
    time::Duration,
};

// ── Binary paths ─────────────────────────────────────────────────────────────

/// Path to the CLI binary under test (auto-resolved by Cargo test runner).
fn cli_bin() -> String {
    // CARGO_BIN_EXE_mcp-v8-cli is injected by Cargo for binaries in the same
    // package (mcp-v8-client).
    env!("CARGO_BIN_EXE_mcp-v8-cli").to_string()
}

/// Path to the server binary.
///
/// Resolved in priority order:
///   1. `SERVER_BIN` environment variable (explicit override)
///   2. `target/release/server` relative to the workspace root
fn server_bin() -> String {
    if let Ok(bin) = env::var("SERVER_BIN") {
        return bin;
    }
    // Walk up from the manifest dir to find the workspace root.
    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    let workspace_root = std::path::Path::new(manifest_dir)
        .parent()
        .unwrap_or_else(|| std::path::Path::new("."));
    let candidate = workspace_root
        .join("target")
        .join("release")
        .join("server");
    if candidate.exists() {
        return candidate.to_string_lossy().to_string();
    }
    // Fallback: assume tests run from workspace root
    "target/release/server".to_string()
}

// ── Server lifecycle ──────────────────────────────────────────────────────────

struct TestServer {
    child: Child,
    pub base_url: String,
}

impl TestServer {
    /// Start the server in stateless HTTP mode on a random free port.
    fn start() -> Result<Self, Box<dyn std::error::Error>> {
        let port = free_port();
        let bin = server_bin();

        let child = Command::new(&bin)
            .args(["--http-port", &port.to_string()])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .map_err(|e| format!("Failed to spawn server '{}': {}", bin, e))?;

        let base_url = format!("http://127.0.0.1:{}", port);

        // Poll until the server accepts requests (up to 15 s).
        let client = Client::builder()
            .timeout(Duration::from_millis(200))
            .build()?;
        let health = format!("{}/api/executions", base_url);
        for _ in 0..150 {
            if client.get(&health).send().is_ok() {
                return Ok(TestServer { child, base_url });
            }
            sleep(Duration::from_millis(100));
        }

        Err("Server did not become ready within 15 s".into())
    }
}

impl Drop for TestServer {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// Return a currently free TCP port on 127.0.0.1.
fn free_port() -> u16 {
    TcpListener::bind("127.0.0.1:0")
        .expect("Failed to bind ephemeral port")
        .local_addr()
        .expect("No local addr")
        .port()
}

// ── CLI helpers ───────────────────────────────────────────────────────────────

/// Run the CLI with the given arguments and return (exit_code, stdout, stderr).
fn run_cli(base_url: &str, args: &[&str]) -> (i32, String, String) {
    let bin = cli_bin();
    let output = Command::new(&bin)
        .arg("--url")
        .arg(base_url)
        .args(args)
        .output()
        .unwrap_or_else(|e| panic!("Failed to run CLI '{}': {}", bin, e));

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let code = output.status.code().unwrap_or(-1);
    (code, stdout, stderr)
}

/// Extract the first UUID-shaped token from `text`.
fn extract_uuid(text: &str) -> Option<String> {
    let re = regex_simple(text);
    re
}

fn regex_simple(text: &str) -> Option<String> {
    // Simple hand-rolled UUID extractor — avoids adding the `regex` dep.
    for word in text.split_whitespace() {
        let w = word.trim_matches(|c: char| !c.is_alphanumeric() && c != '-');
        let parts: Vec<&str> = w.split('-').collect();
        if parts.len() == 5
            && parts[0].len() == 8
            && parts[1].len() == 4
            && parts[2].len() == 4
            && parts[3].len() == 4
            && parts[4].len() == 12
            && parts.iter().all(|p| p.chars().all(|c| c.is_ascii_hexdigit()))
        {
            return Some(w.to_string());
        }
    }
    None
}

/// Poll `executions get <id>` until status is Completed/Failed/TimedOut (or timeout).
/// Returns the final JSON response on success; panics on timeout.
fn poll_until_terminal(base_url: &str, id: &str, max_secs: u64) -> Value {
    let deadline = std::time::Instant::now() + Duration::from_secs(max_secs);
    loop {
        assert!(
            std::time::Instant::now() < deadline,
            "Timed out waiting for execution {} to reach terminal state",
            id
        );
        let (code, stdout, _) = run_cli(base_url, &["--json", "executions", "get", id]);
        assert_eq!(code, 0, "executions get should exit 0");
        if let Ok(v) = serde_json::from_str::<Value>(&stdout) {
            let status = v["status"].as_str().unwrap_or("").to_lowercase();
            match status.as_str() {
                "completed" | "failed" | "timedout" | "timed_out" => return v,
                _ => {}
            }
        }
        sleep(Duration::from_millis(500));
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

/// Test 1 — `exec`: submits code, captures execution_id.
#[test]
fn test_exec_captures_execution_id() {
    let server = TestServer::start().expect("Failed to start server");

    let (code, stdout, _stderr) = run_cli(&server.base_url, &["exec", "console.log(42)"]);
    assert_eq!(code, 0, "exec should exit 0");

    let id = extract_uuid(&stdout).expect("Should find an execution_id UUID in exec output");
    assert!(!id.is_empty(), "execution_id should be non-empty");
}

/// Test 2 — `executions list`: exits 0 and produces output.
#[test]
fn test_executions_list() {
    let server = TestServer::start().expect("Failed to start server");

    // Submit something first so the list is never empty.
    run_cli(&server.base_url, &["exec", "1+1"]);

    let (code, stdout, _) = run_cli(&server.base_url, &["executions", "list"]);
    assert_eq!(code, 0, "executions list should exit 0");
    assert!(!stdout.trim().is_empty(), "executions list should produce output");
}

/// Test 3 — `executions get`: status field is present in the output.
#[test]
fn test_executions_get_has_status() {
    let server = TestServer::start().expect("Failed to start server");

    let (_, submit_out, _) = run_cli(&server.base_url, &["exec", "console.log(99)"]);
    let id = extract_uuid(&submit_out).expect("Should get execution_id from exec");

    let (code, stdout, _) = run_cli(&server.base_url, &["executions", "get", &id]);
    assert_eq!(code, 0, "executions get should exit 0");
    assert!(
        stdout.to_lowercase().contains("status"),
        "executions get output should contain 'status', got: {}",
        stdout
    );
}

/// Test 4 — `executions output`: output of `console.log(42)` contains "42".
#[test]
fn test_executions_output_contains_expected_value() {
    let server = TestServer::start().expect("Failed to start server");

    let (_, submit_out, _) = run_cli(&server.base_url, &["exec", "console.log(42)"]);
    let id = extract_uuid(&submit_out).expect("Should get execution_id from exec");

    // Wait for completion before reading output.
    poll_until_terminal(&server.base_url, &id, 30);

    let (code, stdout, _) = run_cli(&server.base_url, &["executions", "output", &id]);
    assert_eq!(code, 0, "executions output should exit 0");
    assert!(
        stdout.contains("42"),
        "Output should contain '42', got: {}",
        stdout
    );
}

/// Test 5 — exec + poll loop: `2+2` completes and output contains "4".
#[test]
fn test_exec_poll_until_completed() {
    let server = TestServer::start().expect("Failed to start server");

    let (_, submit_out, _) = run_cli(&server.base_url, &["exec", "console.log(2+2)"]);
    let id = extract_uuid(&submit_out).expect("Should get execution_id from exec");

    let final_resp = poll_until_terminal(&server.base_url, &id, 30);
    let status = final_resp["status"].as_str().unwrap_or("").to_lowercase();
    assert_eq!(status, "completed", "Execution should complete successfully");

    let (code, stdout, _) = run_cli(&server.base_url, &["executions", "output", &id]);
    assert_eq!(code, 0, "executions output should exit 0");
    assert!(
        stdout.contains('4'),
        "Output of 2+2 should contain '4', got: {}",
        stdout
    );
}

/// Test 6 — `--json` flag: `exec --json` produces valid JSON.
#[test]
fn test_exec_json_flag_produces_valid_json() {
    let server = TestServer::start().expect("Failed to start server");

    let (code, stdout, _) =
        run_cli(&server.base_url, &["--json", "exec", r#"console.log("json-test")"#]);
    assert_eq!(code, 0, "exec --json should exit 0");

    let parsed: Result<Value, _> = serde_json::from_str(&stdout);
    assert!(
        parsed.is_ok(),
        "exec --json output should be valid JSON, got: {}",
        stdout
    );
}

/// Test 7 — `executions cancel`: submit infinite loop, cancel it, assert exit 0.
#[test]
fn test_executions_cancel() {
    let server = TestServer::start().expect("Failed to start server");

    let (_, submit_out, _) = run_cli(&server.base_url, &["exec", "while(true){}"]);
    let id = extract_uuid(&submit_out).expect("Should get execution_id from exec");

    // Cancel immediately — don't wait for the execution to finish.
    let (cancel_code, _stdout, _stderr) =
        run_cli(&server.base_url, &["executions", "cancel", &id]);
    assert_eq!(cancel_code, 0, "executions cancel should exit 0");
}

//! End-to-end test for upstream MCP tool stubbing.
//!
//! Spins up two MCPJS instances over stdio:
//!
//!   * **upstream**: a plain MCPJS server (default tools).
//!   * **outer**: another MCPJS server configured to connect to `upstream`
//!     via `--mcp-server upstream=stdio:<server-bin>:--directory-path:...`.
//!
//! The outer server should advertise `runjs__upstream__run_js` (and the other
//! upstream tools) as stubs in `tools/list`. Calling one of those stubs
//! should return an instructional text result telling the caller to invoke
//! the tool from JavaScript via `run_js` + `mcp.callTool(...)`.

use serde_json::{json, Value};
use std::process::Stdio;
use std::time::Duration;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, Command};
use tokio::time::timeout;

mod common;

struct OuterServer {
    child: Child,
    stdin: tokio::process::ChildStdin,
    stdout: BufReader<tokio::process::ChildStdout>,
}

impl OuterServer {
    /// Start an MCPJS server on stdio whose `--mcp-server upstream=stdio:...`
    /// points at a second MCPJS subprocess. `extra_args` lets a test pass
    /// additional flags (e.g. `--mcp-stubs false` or
    /// `--mcp-stub-prefix rj_`).
    async fn start_with_args(
        outer_heap: &str,
        upstream_heap: &str,
        extra_args: &[&str],
    ) -> Result<Self, Box<dyn std::error::Error>> {
        let server_bin = env!("CARGO_BIN_EXE_server");

        // The argument format is `name=stdio:command:arg1:arg2...`. We want the
        // upstream invocation to be `<server_bin> --heap-store dir --heap-dir <upstream_heap>`.
        let upstream_arg = format!(
            "upstream=stdio:{}:--heap-store:dir:--heap-dir:{}",
            server_bin, upstream_heap
        );

        let mut args: Vec<String> = vec![
            "--heap-store".to_string(),
            "dir".to_string(),
            "--heap-dir".to_string(),
            outer_heap.to_string(),
            "--mcp-server".to_string(),
            upstream_arg,
        ];
        args.extend(extra_args.iter().map(|s| s.to_string()));

        let mut child = Command::new(server_bin)
            .args(&args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()?;

        let stdin = child.stdin.take().expect("stdin");
        let stdout = BufReader::new(child.stdout.take().expect("stdout"));

        // Give the outer server time to spawn the upstream + handshake.
        tokio::time::sleep(Duration::from_millis(1500)).await;

        Ok(Self { child, stdin, stdout })
    }

    async fn start(outer_heap: &str, upstream_heap: &str) -> Result<Self, Box<dyn std::error::Error>> {
        Self::start_with_args(outer_heap, upstream_heap, &[]).await
    }

    async fn send(&mut self, msg: Value) -> Result<Value, Box<dyn std::error::Error>> {
        let s = format!("{}\n", serde_json::to_string(&msg)?);
        self.stdin.write_all(s.as_bytes()).await?;
        self.stdin.flush().await?;
        let mut line = String::new();
        timeout(Duration::from_secs(10), self.stdout.read_line(&mut line)).await??;
        Ok(serde_json::from_str(&line)?)
    }

    async fn send_notification(&mut self, msg: Value) -> Result<(), Box<dyn std::error::Error>> {
        let s = format!("{}\n", serde_json::to_string(&msg)?);
        self.stdin.write_all(s.as_bytes()).await?;
        self.stdin.flush().await?;
        Ok(())
    }

    async fn initialize(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        let init = json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "stub-e2e", "version": "1.0.0"}
            }
        });
        let _resp = self.send(init).await?;
        let initialized = json!({
            "jsonrpc": "2.0",
            "method": "notifications/initialized"
        });
        self.send_notification(initialized).await?;
        Ok(())
    }

    async fn stop(mut self) {
        let _ = self.child.kill().await;
    }
}

fn tool_names(list_response: &Value) -> Vec<String> {
    list_response["result"]["tools"]
        .as_array()
        .map(|arr| {
            arr.iter()
                .filter_map(|t| t.get("name").and_then(|n| n.as_str()).map(String::from))
                .collect()
        })
        .unwrap_or_default()
}

#[tokio::test]
async fn outer_server_advertises_upstream_tools_as_stubs() -> Result<(), Box<dyn std::error::Error>> {
    let outer_heap = common::create_temp_heap_dir() + "-outer";
    let upstream_heap = common::create_temp_heap_dir() + "-upstream";
    std::fs::create_dir_all(&outer_heap).ok();
    std::fs::create_dir_all(&upstream_heap).ok();

    let mut server = OuterServer::start(&outer_heap, &upstream_heap).await?;
    server.initialize().await?;

    // Ask for the tool list.
    let list = server
        .send(json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/list",
            "params": {}
        }))
        .await?;

    let names = tool_names(&list);
    // Native tools still present.
    assert!(names.contains(&"run_js".to_string()), "native run_js missing: {:?}", names);
    // Upstream tools stubbed: at minimum, run_js from upstream.
    assert!(
        names.contains(&"runjs__upstream__run_js".to_string()),
        "expected runjs__upstream__run_js in tool list, got: {:?}",
        names,
    );
    // Several upstream tools should be stubbed (run_js, get_execution, list_executions, ...).
    let stub_count = names.iter().filter(|n| n.starts_with("runjs__upstream__")).count();
    assert!(stub_count >= 2, "expected multiple upstream stubs, got: {:?}", names);

    // Stub schemas should mirror the upstream tool's schema. For run_js
    // upstream tool, the stub should describe a `code` parameter.
    let stub = list["result"]["tools"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t.get("name").and_then(|n| n.as_str()) == Some("runjs__upstream__run_js"))
        .expect("stub present");
    let schema = &stub["inputSchema"];
    assert!(
        schema["properties"]["code"].is_object(),
        "stub schema should have `code` property; got {}",
        serde_json::to_string_pretty(schema).unwrap_or_default(),
    );
    let desc = stub["description"].as_str().unwrap_or_default();
    assert!(desc.contains("run_js"), "description: {}", desc);
    assert!(desc.contains("mcp.callTool"), "description: {}", desc);

    server.stop().await;
    common::cleanup_heap_dir(&outer_heap);
    common::cleanup_heap_dir(&upstream_heap);
    Ok(())
}

#[tokio::test]
async fn calling_a_stub_returns_run_js_instructions() -> Result<(), Box<dyn std::error::Error>> {
    let outer_heap = common::create_temp_heap_dir() + "-outer2";
    let upstream_heap = common::create_temp_heap_dir() + "-upstream2";
    std::fs::create_dir_all(&outer_heap).ok();
    std::fs::create_dir_all(&upstream_heap).ok();

    let mut server = OuterServer::start(&outer_heap, &upstream_heap).await?;
    server.initialize().await?;

    let resp = server
        .send(json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/call",
            "params": {
                "name": "runjs__upstream__run_js",
                "arguments": {"code": "return 1 + 1;"}
            }
        }))
        .await?;

    // Expect a successful call_tool result whose first content block tells
    // the caller to invoke the tool from JS instead.
    assert_eq!(resp["result"]["isError"], json!(false));
    let text = resp["result"]["content"][0]["text"]
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert!(text.contains("mcp.callTool"), "stub call text: {}", text);
    assert!(text.contains("upstream"), "stub call text: {}", text);
    assert!(text.contains("run_js"), "stub call text: {}", text);
    assert!(text.contains("return 1 + 1"), "stub call text should echo args: {}", text);

    // Sanity: a non-stub native tool still dispatches normally.
    let resp = server
        .send(json!({
            "jsonrpc": "2.0",
            "id": 3,
            "method": "tools/call",
            "params": {
                "name": "list_executions",
                "arguments": {}
            }
        }))
        .await?;
    // Native tool responds with structured executions JSON, not the stub
    // instruction text.
    let text = resp["result"]["content"][0]["text"]
        .as_str()
        .unwrap_or_default()
        .to_string();
    assert!(!text.contains("mcp.callTool"), "native list_executions should not return stub text: {}", text);

    server.stop().await;
    common::cleanup_heap_dir(&outer_heap);
    common::cleanup_heap_dir(&upstream_heap);
    Ok(())
}

#[tokio::test]
async fn mcp_stub_prefix_flag_overrides_default() -> Result<(), Box<dyn std::error::Error>> {
    let outer_heap = common::create_temp_heap_dir() + "-outer3";
    let upstream_heap = common::create_temp_heap_dir() + "-upstream3";
    std::fs::create_dir_all(&outer_heap).ok();
    std::fs::create_dir_all(&upstream_heap).ok();

    let mut server = OuterServer::start_with_args(
        &outer_heap,
        &upstream_heap,
        &["--mcp-stub-prefix", "rj_"],
    )
    .await?;
    server.initialize().await?;

    let list = server
        .send(json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/list",
            "params": {}
        }))
        .await?;
    let names = tool_names(&list);
    // Stubs use the new prefix.
    assert!(
        names.contains(&"rj_upstream__run_js".to_string()),
        "expected rj_upstream__run_js in tool list, got: {:?}",
        names,
    );
    // The default prefix is no longer present.
    assert!(
        !names.iter().any(|n| n.starts_with("runjs__")),
        "default-prefixed stubs should not appear: {:?}",
        names,
    );

    server.stop().await;
    common::cleanup_heap_dir(&outer_heap);
    common::cleanup_heap_dir(&upstream_heap);
    Ok(())
}

#[tokio::test]
async fn mcp_stubs_disabled_flag_hides_stubs() -> Result<(), Box<dyn std::error::Error>> {
    let outer_heap = common::create_temp_heap_dir() + "-outer4";
